-- Candidate only. Applied exclusively to isolated local D1 during development.
CREATE TABLE IF NOT EXISTS v4c_control(id INTEGER PRIMARY KEY CHECK(id=1), input_version INTEGER NOT NULL CHECK(input_version>=0));
INSERT OR IGNORE INTO v4c_control VALUES(1,0);
CREATE TABLE IF NOT EXISTS v4c_input_generations(version INTEGER PRIMARY KEY, created_at TEXT NOT NULL, reason TEXT NOT NULL);
INSERT OR IGNORE INTO v4c_input_generations VALUES(0,'1970-01-01T00:00:00.000Z','empty');
CREATE TABLE IF NOT EXISTS v4c_objects(object_id TEXT PRIMARY KEY, sha256 TEXT NOT NULL, byte_length INTEGER NOT NULL CHECK(byte_length BETWEEN 1 AND 8388608), storage_encoding TEXT NOT NULL CHECK(storage_encoding IN ('identity','gzip')), storage_sha256 TEXT NOT NULL, storage_bytes INTEGER NOT NULL CHECK(storage_bytes BETWEEN 1 AND 8388608), chunk_count INTEGER NOT NULL CHECK(chunk_count BETWEEN 1 AND 128), complete INTEGER NOT NULL DEFAULT 0 CHECK(complete IN (0,1)), content_kind TEXT);
CREATE TABLE IF NOT EXISTS v4c_chunks(object_id TEXT NOT NULL REFERENCES v4c_objects(object_id), chunk_index INTEGER NOT NULL, sha256 TEXT NOT NULL, body BLOB NOT NULL CHECK(length(body)<=98304), PRIMARY KEY(object_id,chunk_index));
CREATE TABLE IF NOT EXISTS v4c_input_files(version INTEGER NOT NULL REFERENCES v4c_input_generations(version), path TEXT NOT NULL, object_id TEXT NOT NULL REFERENCES v4c_objects(object_id), PRIMARY KEY(version,path));
CREATE TABLE IF NOT EXISTS v4c_records(record_id TEXT NOT NULL, revision INTEGER NOT NULL CHECK(revision>0), kind TEXT NOT NULL, payload_json TEXT NOT NULL CHECK(length(CAST(payload_json AS BLOB))<=131072), sha256 TEXT NOT NULL, voided INTEGER NOT NULL DEFAULT 0, source_path TEXT, source_at TEXT, data_status TEXT NOT NULL, review_status TEXT NOT NULL, updated_at TEXT NOT NULL, input_version INTEGER NOT NULL, PRIMARY KEY(record_id,revision));
CREATE INDEX IF NOT EXISTS v4c_record_kind ON v4c_records(kind,updated_at);
CREATE TABLE IF NOT EXISTS v4c_jobs(job_key TEXT PRIMARY KEY, run_id TEXT NOT NULL, audit_sha256 TEXT NOT NULL, lease_digest TEXT NOT NULL, lease_until INTEGER NOT NULL, attempt INTEGER NOT NULL CHECK(attempt BETWEEN 1 AND 3), status TEXT NOT NULL, state TEXT NOT NULL, report_id TEXT, sha256 TEXT, input_version INTEGER, started_at TEXT NOT NULL, updated_at TEXT NOT NULL, code TEXT, verified_at TEXT, readback_scope TEXT);
CREATE TABLE IF NOT EXISTS v4c_events(event_id TEXT PRIMARY KEY, job_key TEXT NOT NULL REFERENCES v4c_jobs(job_key), state TEXT NOT NULL, at TEXT NOT NULL, code TEXT);
CREATE TABLE IF NOT EXISTS v4c_uploads(upload_id TEXT PRIMARY KEY, job_key TEXT, expected_version INTEGER NOT NULL, manifest_json TEXT NOT NULL CHECK(length(CAST(manifest_json AS BLOB))<=524288), manifest_sha256 TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, report_id TEXT, report_sha256 TEXT);
CREATE TABLE IF NOT EXISTS v4c_upload_items(upload_id TEXT NOT NULL REFERENCES v4c_uploads(upload_id), file_index INTEGER NOT NULL, object_id TEXT NOT NULL REFERENCES v4c_objects(object_id), path TEXT, PRIMARY KEY(upload_id,file_index));
CREATE TABLE IF NOT EXISTS v4c_reports(report_id TEXT PRIMARY KEY, object_id TEXT NOT NULL REFERENCES v4c_objects(object_id), sha256 TEXT NOT NULL, generated_at TEXT NOT NULL, as_of TEXT NOT NULL, source_status TEXT NOT NULL, stored_at TEXT NOT NULL, job_key TEXT NOT NULL REFERENCES v4c_jobs(job_key), input_version INTEGER NOT NULL, result_version INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS v4c_report_date ON v4c_reports(generated_at DESC);
CREATE TABLE IF NOT EXISTS v4c_latest(id INTEGER PRIMARY KEY CHECK(id=1), report_id TEXT NOT NULL REFERENCES v4c_reports(report_id), sha256 TEXT NOT NULL, generated_at TEXT NOT NULL, verified_at TEXT NOT NULL, job_key TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS v4c_notifications(job_key TEXT PRIMARY KEY REFERENCES v4c_jobs(job_key), report_id TEXT NOT NULL UNIQUE REFERENCES v4c_reports(report_id), sha256 TEXT NOT NULL, token_digest TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('claimed','accepted','unknown','rejected')), claimed_at TEXT NOT NULL, updated_at TEXT NOT NULL, result_json TEXT);
CREATE TABLE IF NOT EXISTS v4c_nonces(nonce TEXT PRIMARY KEY, expires INTEGER NOT NULL);
